-- ============================================================
-- Clean Schema Migration
-- IDs are 7-character alphanumeric strings generated by the app (e.g. "A3K9X2M").
-- Run this against a fresh database.
-- ============================================================

-- ============================================================
-- 0. CATALOG TABLES — ⚠️ RECONSTRUCTED FROM THE REPO, *NOT* THE LIVE/PROD SCHEMA
-- ------------------------------------------------------------
-- On production, products / product_images / categories / coupons are owned by the
-- seller/admin app and were created directly on the DB (they pre-date this file).
-- They are defined here ONLY so a fresh TEST database can be built and seeded
-- end-to-end. Column names and types were derived from DATABASE.md, the seed
-- scripts, and the route queries — live column defaults, constraints, extra columns
-- or ID strategies MAY DIFFER. Do NOT run this section against production.
-- ============================================================

CREATE EXTENSION IF NOT EXISTS "uuid-ossp";  -- required by uuid_generate_v4() in the seed scripts

CREATE TABLE IF NOT EXISTS categories (
  id          UUID       PRIMARY KEY DEFAULT uuid_generate_v4(),
  name        TEXT       NOT NULL,
  parent_id   UUID       REFERENCES categories(id) ON DELETE SET NULL,
  description TEXT,
  image_url   TEXT,
  is_active   BOOLEAN    NOT NULL DEFAULT true,
  created_at  TIMESTAMP  NOT NULL DEFAULT NOW(),
  updated_at  TIMESTAMP  NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS products (
  id                    UUID          PRIMARY KEY DEFAULT uuid_generate_v4(),
  user_id               VARCHAR(7),                    -- seller id; not FK-enforced in the test schema
  product_name          TEXT          NOT NULL,
  description           TEXT,
  category_id           UUID,                          -- loose ref to categories(id); read but not FK-enforced by the customer app
  deepest_category_name TEXT,
  category_path         JSONB,
  price                 NUMERIC(10,2) NOT NULL,
  quantity              INTEGER       NOT NULL DEFAULT 0,
  in_stock              BOOLEAN       NOT NULL DEFAULT true,
  is_approved           BOOLEAN       NOT NULL DEFAULT false,
  approval_notes        TEXT,
  search_tags           TEXT[],
  search_vector         TSVECTOR,
  extracted_attributes  JSONB,
  size_quantities       JSONB,
  created_at            TIMESTAMP     NOT NULL DEFAULT NOW(),
  updated_at            TIMESTAMP     NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS product_images (
  id            UUID       PRIMARY KEY DEFAULT uuid_generate_v4(),
  product_id    UUID       NOT NULL REFERENCES products(id) ON DELETE CASCADE,
  image_url     TEXT       NOT NULL,
  display_order INTEGER    NOT NULL DEFAULT 0,
  created_at    TIMESTAMP  NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS coupons (
  id                  UUID          PRIMARY KEY DEFAULT uuid_generate_v4(),
  code                VARCHAR(50)   NOT NULL UNIQUE,
  description         TEXT,
  discount_type       VARCHAR(20)   NOT NULL,           -- 'percentage' | 'fixed'
  discount_value      NUMERIC(10,2) NOT NULL,
  min_order_amount    NUMERIC(10,2) NOT NULL DEFAULT 0,
  max_discount_amount NUMERIC(10,2),
  valid_from          TIMESTAMP     NOT NULL DEFAULT NOW(),
  valid_until         TIMESTAMP,
  usage_limit         INTEGER,
  usage_count         INTEGER       NOT NULL DEFAULT 0,
  is_active           BOOLEAN       NOT NULL DEFAULT true,
  created_at          TIMESTAMP     NOT NULL DEFAULT NOW(),
  updated_at          TIMESTAMP     NOT NULL DEFAULT NOW()
);

-- ── 1. users ──────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS users (
  id                         VARCHAR(7)   PRIMARY KEY,
  user_name                  VARCHAR(255) UNIQUE NOT NULL,
  name                       VARCHAR(255) NOT NULL,
  email                      VARCHAR(255) UNIQUE NOT NULL,
  mobile                     VARCHAR(20)  UNIQUE,
  password_hash              VARCHAR(255),
  google_id                  VARCHAR(255),
  apple_id                   VARCHAR(255),
  user_role                  VARCHAR(50)  NOT NULL DEFAULT 'customer',
  is_verified                BOOLEAN      NOT NULL DEFAULT false,
  is_active                  BOOLEAN      NOT NULL DEFAULT true,
  dob                        DATE,
  gender                     VARCHAR(50),
  profile_image              TEXT,
  receive_push_notifications BOOLEAN      NOT NULL DEFAULT true,
  receive_email_updates      BOOLEAN      NOT NULL DEFAULT false,
  receive_order_updates      BOOLEAN      NOT NULL DEFAULT true,
  created_at                 TIMESTAMP    NOT NULL DEFAULT NOW(),
  updated_at                 TIMESTAMP    NOT NULL DEFAULT NOW()
);

-- ── 2. refresh_tokens ─────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS refresh_tokens (
  id         VARCHAR(7) PRIMARY KEY,
  user_id    VARCHAR(7) NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token      TEXT       NOT NULL,
  expires_at TIMESTAMP  NOT NULL,
  created_at TIMESTAMP  NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_refresh_tokens_user_id ON refresh_tokens(user_id);

-- ── 3. auth_tokens ────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS auth_tokens (
  id         VARCHAR(7)  PRIMARY KEY,
  user_id    VARCHAR(7)  REFERENCES users(id) ON DELETE CASCADE,
  email      VARCHAR(255),
  mobile     VARCHAR(20),
  token      TEXT        NOT NULL,
  token_type VARCHAR(50) NOT NULL,
  is_used    BOOLEAN     NOT NULL DEFAULT false,
  expires_at TIMESTAMP   NOT NULL,
  created_at TIMESTAMP   NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_auth_tokens_user_id ON auth_tokens(user_id);
CREATE INDEX IF NOT EXISTS idx_auth_tokens_token   ON auth_tokens(token);

-- ── 3b. pending_signups ───────────────────────────────────────────────────────
-- Holds signup data until the email OTP is verified. The users row is only
-- created after verification, so unverified emails/phones never occupy users.
CREATE TABLE IF NOT EXISTS pending_signups (
  id            VARCHAR(7)   PRIMARY KEY,
  email         VARCHAR(255) UNIQUE NOT NULL,
  name          VARCHAR(255) NOT NULL,
  mobile        VARCHAR(20),
  user_name     VARCHAR(255) NOT NULL,
  password_hash VARCHAR(255) NOT NULL,
  otp_hash      TEXT         NOT NULL,
  expires_at    TIMESTAMP    NOT NULL,
  created_at    TIMESTAMP    NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_pending_signups_email ON pending_signups(email);

-- ── 4. addresses ──────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS addresses (
  id            VARCHAR(7)   PRIMARY KEY,
  user_id       VARCHAR(7)   NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  name          TEXT         NOT NULL,
  phone         TEXT,
  address_line1 TEXT         NOT NULL,
  address_line2 TEXT,
  city          TEXT         NOT NULL,
  state         TEXT         NOT NULL,
  pincode       TEXT         NOT NULL,
  country       TEXT         NOT NULL DEFAULT 'India',
  landmark      TEXT,
  label         VARCHAR(50)  NOT NULL DEFAULT 'Home',
  is_default    BOOLEAN      NOT NULL DEFAULT false,
  created_at    TIMESTAMP    NOT NULL DEFAULT NOW(),
  updated_at    TIMESTAMP    NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_addresses_user_id ON addresses(user_id);

-- ── 5. cart_items ─────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS cart_items (
  id           VARCHAR(7)    PRIMARY KEY,
  user_id      VARCHAR(7)    NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  product_id   UUID          NOT NULL REFERENCES products(id) ON DELETE CASCADE,
  quantity     INTEGER       NOT NULL DEFAULT 1 CHECK (quantity > 0),
  price_at_add NUMERIC(10,2) NOT NULL,
  created_at   TIMESTAMP     NOT NULL DEFAULT NOW(),
  updated_at   TIMESTAMP     NOT NULL DEFAULT NOW(),
  UNIQUE(user_id, product_id)
);
CREATE INDEX IF NOT EXISTS idx_cart_items_user_id ON cart_items(user_id);

-- ── 6. wishlists ──────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS wishlists (
  id         VARCHAR(7) PRIMARY KEY,
  user_id    VARCHAR(7) NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  product_id UUID       NOT NULL REFERENCES products(id) ON DELETE CASCADE,
  created_at TIMESTAMP  NOT NULL DEFAULT NOW(),
  UNIQUE(user_id, product_id)
);
CREATE INDEX IF NOT EXISTS idx_wishlists_user_id ON wishlists(user_id);

-- ── 7. orders ─────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS orders (
  id                 VARCHAR(7)    PRIMARY KEY,
  order_number       VARCHAR(50)   UNIQUE NOT NULL,
  user_id            VARCHAR(7)    NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  status             VARCHAR(50)   NOT NULL DEFAULT 'pending',
  payment_status     VARCHAR(50)   NOT NULL DEFAULT 'pending',
  total_amount       NUMERIC(10,2) NOT NULL DEFAULT 0,
  shipping_amount    NUMERIC(10,2) NOT NULL DEFAULT 0,
  tax_amount         NUMERIC(10,2) NOT NULL DEFAULT 0,
  final_amount       NUMERIC(10,2) NOT NULL DEFAULT 0,
  shipping_address   JSONB         NOT NULL DEFAULT '{}',
  payment_method     VARCHAR(50)   NOT NULL DEFAULT 'cod',
  payment_id         VARCHAR(255),
  notes              TEXT,
  tracking_number    VARCHAR(255),
  estimated_delivery TIMESTAMP,
  created_at         TIMESTAMP     NOT NULL DEFAULT NOW(),
  updated_at         TIMESTAMP     NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_orders_user_id ON orders(user_id);
CREATE INDEX IF NOT EXISTS idx_orders_status  ON orders(status);

-- ── 8. order_items ────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS order_items (
  id           VARCHAR(7)    PRIMARY KEY,
  order_id     VARCHAR(7)    NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
  product_id   UUID          REFERENCES products(id) ON DELETE SET NULL,
  product_name VARCHAR(255)  NOT NULL,
  quantity     INTEGER       NOT NULL CHECK (quantity > 0),
  price        NUMERIC(10,2) NOT NULL,
  image        TEXT,
  variant      VARCHAR(255),
  created_at   TIMESTAMP     NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_order_items_order_id ON order_items(order_id);

-- ── 9. return_requests ───────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS return_requests (
  id             VARCHAR(7)   PRIMARY KEY,
  order_id       VARCHAR(7)   NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
  user_id        VARCHAR(7)   NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  order_item_ids JSONB        NOT NULL DEFAULT '[]'::jsonb,
  reason         TEXT         NOT NULL,
  description    TEXT,
  status         VARCHAR(50)  NOT NULL DEFAULT 'requested',
  picked_up_at   TIMESTAMP,
  refunded_at    TIMESTAMP,
  status_history JSONB        NOT NULL DEFAULT '[]'::jsonb,
  created_at     TIMESTAMP    NOT NULL DEFAULT NOW(),
  updated_at     TIMESTAMP    NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_return_requests_order_id ON return_requests(order_id);
CREATE INDEX IF NOT EXISTS idx_return_requests_user_id  ON return_requests(user_id);

-- ── 10. order_cancellations ──────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS order_cancellations (
  id            VARCHAR(7)   PRIMARY KEY,
  order_id      VARCHAR(7)   NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
  user_id       VARCHAR(7)   NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  reason        TEXT         NOT NULL,
  refund_method VARCHAR(50)  NOT NULL DEFAULT 'original',
  created_at    TIMESTAMP    NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_order_cancellations_order_id ON order_cancellations(order_id);

-- ── 11. wallets ───────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS wallets (
  id         VARCHAR(7)  PRIMARY KEY,
  user_id    VARCHAR(7)  NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,
  balance    TEXT        NOT NULL,
  created_at TIMESTAMP   NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMP   NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_wallets_user_id ON wallets(user_id);

-- ── 12. wallet_transactions ──────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS wallet_transactions (
  id           VARCHAR(7)    PRIMARY KEY,
  wallet_id    VARCHAR(7)    NOT NULL REFERENCES wallets(id) ON DELETE CASCADE,
  user_id      VARCHAR(7)    NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  type         VARCHAR(20)   NOT NULL CHECK (type IN ('credit', 'debit')),
  amount       NUMERIC(10,2) NOT NULL CHECK (amount > 0),
  description  TEXT,
  reference_id VARCHAR(64),
  created_at   TIMESTAMP     NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_wallet_transactions_wallet_id ON wallet_transactions(wallet_id);
CREATE INDEX IF NOT EXISTS idx_wallet_transactions_user_id ON wallet_transactions(user_id);

-- ── 12b. notifications ────────────────────────────────────────────────────────
-- Written by the order-creation, razorpay-verify, and order-confirm flows, and
-- read by the seller notification endpoints. `data` is stored as TEXT holding a
-- JSON-stringified payload (the route handlers call JSON.parse/JSON.stringify),
-- so it must NOT be JSONB. Created here so fresh deployments can place orders.
CREATE TABLE IF NOT EXISTS notifications (
  id         VARCHAR(7)  PRIMARY KEY,
  user_id    VARCHAR(7)  NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  type       VARCHAR(50) NOT NULL,
  title      TEXT        NOT NULL,
  message    TEXT        NOT NULL,
  data       TEXT        NOT NULL DEFAULT '{}',
  is_read    BOOLEAN     NOT NULL DEFAULT false,
  created_at TIMESTAMP   NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_notifications_user_id ON notifications(user_id);
CREATE INDEX IF NOT EXISTS idx_notifications_user_type_unread
  ON notifications(user_id, type, is_read);

-- ── 13-15. products, product_images, product_reviews ──────────────────────────
-- products and product_images tables are managed separately (seeded externally).
-- product_reviews is created here to ensure it exists on fresh DB deployments.

CREATE TABLE IF NOT EXISTS product_reviews (
  id                   VARCHAR(7)    PRIMARY KEY,
  product_id           UUID          NOT NULL REFERENCES products(id) ON DELETE CASCADE,
  user_id              VARCHAR(7)    NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  rating               INTEGER       NOT NULL CHECK (rating >= 1 AND rating <= 5),
  comment              TEXT          NOT NULL,
  images               TEXT          NOT NULL DEFAULT '[]',
  is_verified_purchase BOOLEAN       NOT NULL DEFAULT false,
  is_hidden            BOOLEAN       NOT NULL DEFAULT false,
  created_at           TIMESTAMP     NOT NULL DEFAULT NOW(),
  updated_at           TIMESTAMP     NOT NULL DEFAULT NOW(),
  UNIQUE(product_id, user_id)
);
CREATE INDEX IF NOT EXISTS idx_product_reviews_product_id ON product_reviews(product_id);
CREATE INDEX IF NOT EXISTS idx_product_reviews_user_id    ON product_reviews(user_id);

-- ── 16. UGC moderation (App Store 1.2): review reports + user blocks ───────────
CREATE TABLE IF NOT EXISTS review_reports (
  id               VARCHAR(7) PRIMARY KEY,
  review_id        VARCHAR(7) NOT NULL REFERENCES product_reviews(id) ON DELETE CASCADE,
  reporter_user_id VARCHAR(7) NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  reason           TEXT,
  created_at       TIMESTAMP  NOT NULL DEFAULT NOW(),
  UNIQUE(review_id, reporter_user_id)
);
CREATE INDEX IF NOT EXISTS idx_review_reports_review_id ON review_reports(review_id);

CREATE TABLE IF NOT EXISTS user_blocks (
  id              VARCHAR(7) PRIMARY KEY,
  blocker_user_id VARCHAR(7) NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  blocked_user_id VARCHAR(7) NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at      TIMESTAMP  NOT NULL DEFAULT NOW(),
  UNIQUE(blocker_user_id, blocked_user_id)
);
CREATE INDEX IF NOT EXISTS idx_user_blocks_blocker ON user_blocks(blocker_user_id);

-- Performance indexes for product listing/filtering/sorting (category route).
-- products/product_images are created in section 0 above for test DBs, and pre-exist
-- on prod, so these indexes apply either way (IF NOT EXISTS keeps it idempotent).
CREATE INDEX IF NOT EXISTS idx_products_created_at        ON products(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_products_price             ON products(price);
CREATE INDEX IF NOT EXISTS idx_products_in_stock          ON products(in_stock);
CREATE INDEX IF NOT EXISTS idx_products_deepest_cat_lower ON products(LOWER(deepest_category_name));
CREATE INDEX IF NOT EXISTS idx_product_images_product_id  ON product_images(product_id);
